window.kbPageData["views/entry/k-77a3e1808ca5b796"] = {"key":"entry/k-77a3e1808ca5b796","state":{"route":"entry/k-77a3e1808ca5b796"},"node":{"id":"k-77a3e1808ca5b796","mode":"k","title":"2023年支持高质量共建“一带一路”的八项行动","type":"事实与事件","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":["第三届“一带一路”国际合作高峰论坛宣布支持高质量共建“一带一路”的八项行动"],"qs":["江苏 2024 A类 行测#2"],"current":true,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"2023年10月18日，习近平主席在第三届“一带一路”国际合作高峰论坛开幕式上宣布八项行动，包括构建“一带一路”立体互联互通网络、支持建设开放型世界经济、开展务实合作、促进绿色发展、推动科技创新、支持民间交往、建设廉洁之路、完善“一带一路”国际合作机制。","review":{"definition":"2023年10月18日，习近平主席在第三届“一带一路”国际合作高峰论坛开幕式上宣布八项行动，包括构建“一带一路”立体互联互通网络、支持建设开放型世界经济、开展务实合作、促进绿色发展、推动科技创新、支持民间交往、建设廉洁之路、完善“一带一路”国际合作机制。","explanation":"题中①、②、③分别对应八项行动中的第二项、第八项和第一项。推动科技创新也是八项行动之一，其中对科技创新行动计划的表述是“继续实施”，因此④中的“启动”有误，正确组合为①②③。","references":[],"evidence":"中国支持高质量共建“一带一路”的八项行动","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"江苏 2024 A类 行测#2":{"paper":"江苏 2024 A类 行测","n":2,"mod":"常识判断","src":["f8fec75f67d6d1ba5759.pdf",1],"asrc":["0126a1c8aceee632ea2b.pdf",1],"card":"95d2e7a0de5a673f0bb8eafb","links":[{"id":"k-77a3e1808ca5b796","role":"直接考查","why":"八项行动包括支持建设开放型世界经济、完善国际合作机制和构建立体互联互通网络。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-77a3e1808ca5b796":[["江苏 2024 A类 行测#2"]]}};
